17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.advice.CityAtCapacityException;
32	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitException;
33	import org.springframework.samples.petclinic.rest.advice.DuplicateHouseholdException;
34	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
35	import org.springframework.samples.petclinic.rest.advice.InvalidAddressException;
36	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
37	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
40	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.PetDto;
42	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.samples.petclinic.util.Households;
47	import org.springframework.security.access.prepost.PreAuthorize;
48	import org.springframework.web.bind.annotation.CrossOrigin;
49	import org.springframework.web.bind.annotation.RequestMapping;
50	import org.springframework.web.bind.annotation.RestController;
51	import org.springframework.web.util.UriComponentsBuilder;
52	
53	import jakarta.transaction.Transactional;
54	
55	/**
56	 * @author Vitaliy Fedoriv
57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    private final ClinicService clinicService;
65	
66	    private final OwnerMapper ownerMapper;
67	
68	    private final PetMapper petMapper;
69	
70	    private final VisitMapper visitMapper;
71	
72	    public OwnerRestControllerV1(ClinicService clinicService,
73	                                 OwnerMapper ownerMapper,
74	                                 PetMapper petMapper,
75	                                 VisitMapper visitMapper) {
76	        this.clinicService = clinicService;
77	        this.ownerMapper = ownerMapper;
78	        this.petMapper = petMapper;
79	        this.visitMapper = visitMapper;
80	    }
81	
82	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
83	    @Override
84	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
85	        Collection<Owner> owners;
86	        if (lastName != null) {
87	            owners = this.clinicService.findOwnerByLastName(lastName);
88	        } else {
89	            owners = this.clinicService.findAllOwners();
90	        }
91	        if (owners.isEmpty()) {
92	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
93	        }
94	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
95	    }
96	
97	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
98	    @Override
99	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
100	        Owner owner = this.clinicService.findOwnerById(ownerId);
101	        if (owner == null) {
102	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
103	        }
104	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
105	    }
106	
107	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
108	    @Override
109	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
110	        HttpHeaders headers = new HttpHeaders();
111	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
112	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
113	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
114	        if (registrationDate == null) {
115	            registrationDate = java.time.LocalDate.now();
116	        }
117	        registrationDate = toBusinessDay(registrationDate);
118	        owner.setRegistrationDate(registrationDate);
119	        rejectDailyLimitReached(registrationDate);
120	        rejectCityAtCapacity(owner.getCity());
121	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
122	            rejectDuplicateHousehold(owner.getLastName(), owner.getAddress());
123	        }
124	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
125	        rejectDuplicateTelephone(telephone);
126	        owner.setTelephone(telephone);
127	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
128	        owner.setCustomerCode(assignCustomerCode(owner.getCity(), owner.getLastName()));
129	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
130	        this.clinicService.saveOwner(owner);
131	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
132	        headers.setLocation(UriComponentsBuilder.newInstance()
133	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
134	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
135	    }
136	
137	    /**
138	     * The maximum number of owners that may be created in a single day. Creating an owner once this
139	     * many owners already carry today's {@code registrationDate} is rejected.
140	     */
141	    private static final int DAILY_OWNER_LIMIT = 100;
142	
143	    /**
144	     * Rejects creating an owner once {@value #DAILY_OWNER_LIMIT} or more owners already carry the
145	     * given business day as their {@code registrationDate}. The count is keyed by the
146	     * business-day-adjusted registration date of the owner being created (see
147	     * {@link #toBusinessDay}), so all owners falling on the same business day count together. Owners
148	     * with no {@code registrationDate} are ignored.
149	     *
150	     * @param registrationDate the business-day-adjusted registration date of the owner being created
151	     * @throws DailyOwnerLimitException (429 Too Many Requests) if the daily limit is already reached
152	     */
153	    private void rejectDailyLimitReached(java.time.LocalDate registrationDate) {
154	        long count = this.clinicService.findAllOwners().stream()
155	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
156	            .count();
157	        if (count >= DAILY_OWNER_LIMIT) {
158	            throw new DailyOwnerLimitException(registrationDate);
159	        }
160	    }
161	
162	    /**
163	     * Rolls a registration date forward onto a business day: a Saturday or Sunday is moved forward to
164	     * the following Monday; a weekday is returned unchanged. This applies to the effective
165	     * registration date whether it was supplied in the request or defaulted to the server date, and
166	     * every value derived from the registration date uses the adjusted result.
167	     *
168	     * @param date the effective registration date
169	     * @return {@code date} itself when it is a weekday, otherwise the following Monday
170	     */
171	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
172	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
173	            || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY) {
174	            date = date.plusDays(1);
175	        }
176	        return date;
177	    }
178	
179	    /**
180	     * The maximum number of owners a single city may contain. Creating an owner in a city that
181	     * already holds this many owners is rejected.
182	     */
183	    private static final int CITY_CAPACITY = 50;
184	
185	    /**
186	     * Rejects creating an owner whose city already contains {@value #CITY_CAPACITY} or more owners.
187	     * Owners are counted per city comparing the city name case-insensitively (a {@code null} city is
188	     * treated as empty), the same way {@link #assignCustomerCode} counts a city's owners.
189	     *
190	     * @param city the city of the owner being created
191	     * @throws CityAtCapacityException (409 Conflict) if the city is already at capacity
192	     */
193	    private void rejectCityAtCapacity(String city) {
194	        String cityValue = city == null ? "" : city;
195	        long count = this.clinicService.findAllOwners().stream()
196	            .filter(existing -> cityValue.equalsIgnoreCase(
197	                existing.getCity() == null ? "" : existing.getCity()))
198	            .count();
199	        if (count >= CITY_CAPACITY) {
200	            throw new CityAtCapacityException(city);
201	        }
202	    }
203	
204	    /**
205	     * Assigns an owner's {@code customerCode} on create, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
206	     * where CITY3 is the upper-cased first three letters of the city, LAST3 the upper-cased first
207	     * three letters of the last name and NNNN a per-city 4-digit zero-padded sequence equal to one
208	     * more than the number of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
209	     *
210	     * @param city the owner's city
211	     * @param lastName the owner's last name
212	     * @return the assigned customer code
213	     */
214	    private String assignCustomerCode(String city, String lastName) {
215	        String city3 = prefix3(city);
216	        String last3 = prefix3(lastName);
217	        String cityValue = city == null ? "" : city;
218	        int sequence = (int) this.clinicService.findAllOwners().stream()
219	            .filter(existing -> cityValue.equalsIgnoreCase(
220	                existing.getCity() == null ? "" : existing.getCity()))
221	            .count() + 1;
222	        return String.format("%s-%s-%04d", city3, last3, sequence);
223	    }
224	
225	    /**
226	     * Returns the upper-cased first three letters of the given value, or fewer if the value is
227	     * shorter, treating {@code null} as empty.
228	     */
229	    private String prefix3(String value) {
230	        String name = value == null ? "" : value;
231	        return name.substring(0, Math.min(3, name.length()))
232	            .toUpperCase(java.util.Locale.ROOT);
233	    }
234	
235	    /**
236	     * Counts how many existing owners share the given first and last name, compared
237	     * case-insensitively, at the time this owner is created. The value excludes the owner
238	     * being created (which has not yet been saved) and is stored on the new owner and returned
239	     * as its {@code namesakeCount}.
240	     *
241	     * @param firstName the first name of the owner being created
242	     * @param lastName the last name of the owner being created
243	     * @return the number of existing owners with the same first and last name
244	     */
245	    private int countNamesakes(String firstName, String lastName) {
246	        String first = firstName == null ? "" : firstName;
247	        String last = lastName == null ? "" : lastName;
248	        return (int) this.clinicService.findAllOwners().stream()
249	            .filter(existing -> first.equalsIgnoreCase(existing.getFirstName())
250	                && last.equalsIgnoreCase(existing.getLastName()))
251	            .count();
252	    }
253	
254	    /**
255	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
256	     * stripped. A leading '+' and its country code are kept as given; otherwise country code '+61' is
257	     * assumed and a single leading '0' is dropped from the national digits. The resulting number must
258	     * have 8 to 15 digits after the '+'. For example {@code "0412 345 678"} becomes
259	     * {@code "+61412345678"}. The E.164 value is stored and returned.
260	     *
261	     * @param telephone the raw telephone as submitted
262	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
263	     * @throws InvalidTelephoneException (400 Bad Request) if the value cannot form a valid E.164 number
264	     */
265	    private String normalizeTelephone(String telephone) {
266	        String raw = telephone == null ? "" : telephone.trim();
267	        boolean hasCountryCode = raw.startsWith("+");
268	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
269	        if (hasCountryCode) {
270	            cleaned = cleaned.substring(1);
271	        }
272	        String digits;
273	        if (hasCountryCode) {
274	            digits = cleaned;
275	        } else {
276	            if (cleaned.startsWith("0")) {
277	                cleaned = cleaned.substring(1);
278	            }
279	            digits = "61" + cleaned;
280	        }
281	        if (!digits.matches("[0-9]{8,15}")) {
282	            throw new InvalidTelephoneException(telephone);
283	        }
284	        return "+" + digits;
285	    }
286	
287	    /**
288	     * Syntactic email pattern: a non-empty local part, an '@', a domain with at least one dot and a
289	     * multi-character top-level label. Deliberately lenient about the exact character set while still
290	     * rejecting values that are clearly not addresses (e.g. missing '@').
291	     */
292	    private static final java.util.regex.Pattern EMAIL_PATTERN =
293	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$");
294	
295	    /**
296	     * Normalizes an owner's email. Email is optional: a {@code null} or blank value is left as
297	     * {@code null} (no email). When present it must be a syntactically valid address; the value is
298	     * lower-cased before being stored and returned.
299	     *
300	     * @param email the raw email as submitted, may be {@code null}
301	     * @return the lower-cased email, or {@code null} when none was supplied
302	     * @throws InvalidEmailException (400 Bad Request) if a non-blank value is not a valid address
303	     */
304	    private String normalizeEmail(String email) {
305	        if (email == null || email.isBlank()) {
306	            return null;
307	        }
308	        String trimmed = email.trim();
309	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
310	            throw new InvalidEmailException(email);
311	        }
312	        return trimmed.toLowerCase(java.util.Locale.ROOT);
313	    }
314	
315	    /**
316	     * Common street-type abbreviations expanded to their full word during address normalization.
317	     */
318	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS = java.util.Map.of(
319	        "ST", "STREET",
320	        "RD", "ROAD",
321	        "AVE", "AVENUE");
322	
323	    /**
324	     * Normalizes an owner's address on create. Surrounding whitespace is trimmed and internal runs of
325	     * whitespace collapse to a single space, the value is upper-cased and common street-type
326	     * abbreviations are expanded to their full word ({@code ST} to {@code STREET}, {@code RD} to
327	     * {@code ROAD}, {@code AVE} to {@code AVENUE}). For example {@code "  12  main  st "} becomes
328	     * {@code "12 MAIN STREET"}. The normalized value is stored and returned, and is also the form used
329	     * for every address comparison (household duplicate detection and the shared household id).
330	     *
331	     * @param address the raw address as submitted
332	     * @return the normalized address
333	     * @throws InvalidAddressException (400 Bad Request) if the address is blank after normalization
334	     */
335	    private String normalizeAddress(String address) {
336	        String collapsed = (address == null ? "" : address).trim().replaceAll("\\s+", " ");
337	        if (collapsed.isEmpty()) {
338	            throw new InvalidAddressException(address);
339	        }
340	        String[] tokens = collapsed.toUpperCase(java.util.Locale.ROOT).split(" ");
341	        StringBuilder normalized = new StringBuilder(collapsed.length());
342	        for (int i = 0; i < tokens.length; i++) {
343	            if (i > 0) {
344	                normalized.append(' ');
345	            }
346	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
347	        }
348	        return normalized.toString();
349	    }
350	
351	    /**
352	     * Rejects creating an owner whose E.164 telephone is already used by another owner. Telephones of
353	     * existing owners are normalized to E.164 the same way before comparison, so equivalent numbers
354	     * submitted in different formats (e.g. national {@code "0412 345 678"} and international
355	     * {@code "+61 412 345 678"}) are still treated as duplicates.
356	     *
357	     * @param telephone the E.164 telephone of the owner being created
358	     * @throws DuplicateTelephoneException (409 Conflict) if another owner already uses this telephone
359	     */
360	    private void rejectDuplicateTelephone(String telephone) {
361	        boolean duplicate = this.clinicService.findAllOwners().stream()
362	            .map(Owner::getTelephone)
363	            .filter(existing -> existing != null)
364	            .map(this::toE164OrNull)
365	            .filter(existing -> existing != null)
366	            .anyMatch(telephone::equals);
367	        if (duplicate) {
368	            throw new DuplicateTelephoneException(telephone);
369	        }
370	    }
371	
372	    /**
373	     * Normalizes an existing owner's telephone to E.164 for duplicate comparison, returning
374	     * {@code null} instead of throwing when the stored value cannot form a valid E.164 number.
375	     */
376	    private String toE164OrNull(String telephone) {
377	        try {
378	            return normalizeTelephone(telephone);
379	        } catch (InvalidTelephoneException e) {
380	            return null;
381	        }
382	    }
383	
384	    /**
385	     * Rejects creating an owner who shares a household with an existing owner, i.e. another owner
386	     * already has the same last name and the same address. Last names are compared case-insensitively
387	     * with whitespace collapsed; addresses are compared in their normalized form (see
388	     * {@link #normalizeAddress}, which every owner's stored address already uses), so values that
389	     * differ only in letter case, spacing or a common street-type abbreviation still count as a match.
390	     * This check is skipped when the request sets {@code sharesHousehold} to {@code true}.
391	     *
392	     * @param lastName the last name of the owner being created
393	     * @param address the normalized address of the owner being created
394	     * @throws DuplicateHouseholdException (409 Conflict) if another owner shares this household
395	     */
396	    private void rejectDuplicateHousehold(String lastName, String address) {
397	        String normalizedLastName = Households.normalize(lastName);
398	        String normalizedAddress = Households.normalize(address);
399	        boolean duplicate = this.clinicService.findAllOwners().stream()
400	            .anyMatch(existing ->
401	                Households.normalize(existing.getLastName()).equals(normalizedLastName)
402	                    && Households.normalize(existing.getAddress()).equals(normalizedAddress));
403	        if (duplicate) {
404	            throw new DuplicateHouseholdException(lastName, address);
405	        }
406	    }
407	
408	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
409	    @Override
410	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
411	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
412	        if (currentOwner == null) {
413	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
414	        }
415	        currentOwner.setAddress(ownerFieldsDto.getAddress());
416	        currentOwner.setCity(ownerFieldsDto.getCity());
417	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
418	        currentOwner.setLastName(ownerFieldsDto.getLastName());
419	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
420	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
421	        this.clinicService.saveOwner(currentOwner);
422	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
423	    }
424	
425	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
426	    @Transactional
427	    @Override
428	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
429	        Owner owner = this.clinicService.findOwnerById(ownerId);
430	        if (owner == null) {
431	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
432	        }
433	        this.clinicService.deleteOwner(owner);
434	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
435	    }
436	
437	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
438	    @Override
439	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
440	        Owner owner = this.clinicService.findOwnerById(ownerId);
441	        if (owner == null) {
442	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
443	        }
444	        HttpHeaders headers = new HttpHeaders();
445	        Pet pet = petMapper.toPet(petFieldsDto);
446	        owner.setId(ownerId);
447	        pet.setOwner(owner);
448	        pet.getType().setName(null);
449	        this.clinicService.savePet(pet);
450	        PetDto petDto = petMapper.toPetDto(pet);
451	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
452	            .buildAndExpand(pet.getId()).toUri());
453	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
454	    }
455	
456	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
457	    @Override
458	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
459	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
460	        if (currentOwner != null) {
461	            Pet currentPet = this.clinicService.findPetById(petId);
462	            if (currentPet != null) {
463	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
464	                currentPet.setName(petFieldsDto.getName());
465	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
466	                this.clinicService.savePet(currentPet);
467	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
468	            }
469	        }
470	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
471	    }
472	
473	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
474	    @Override
475	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
476	        HttpHeaders headers = new HttpHeaders();
477	        Visit visit = visitMapper.toVisit(visitFieldsDto);
478	        Pet pet = new Pet();
479	        pet.setId(petId);
480	        visit.setPet(pet);
481	        this.clinicService.saveVisit(visit);
482	        VisitDto visitDto = visitMapper.toVisitDto(visit);
483	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
484	            .buildAndExpand(visit.getId()).toUri());
485	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
486	    }
487	
488	
489	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
490	    @Override
491	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
492	        Owner owner = this.clinicService.findOwnerById(ownerId);
493	        if (owner != null) {
494	            Pet pet = owner.getPet(petId);
495	            if (pet != null) {
496	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
497	            }
498	        }
499	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
500	    }
501	}
